changeSet.sql:
CREATE OR REPLACE TRIGGER trg_sesion_usuario_revocacion
BEFORE UPDATE ON sesion_usuario
FOR EACH ROW
WHEN (OLD.revoked_at IS NOT NULL)
BEGIN
    :NEW.revoked_at        := :OLD.revoked_at;
    :NEW.revocation_reason := :OLD.revocation_reason;
    :NEW.expires_at        := :OLD.expires_at;
    :NEW.last_activity_at  := :OLD.last_activity_at;
END;

DECLARE
    v_user      NUMBER;
    v_sid       VARCHAR2(36);
    v_t0        TIMESTAMP := SYS_EXTRACT_UTC(SYSTIMESTAMP);
    v_rev1      TIMESTAMP;
    v_rev2      TIMESTAMP;
    v_reason    VARCHAR2(30);
    v_cause     VARCHAR2(30);
    v_afectadas NUMBER;
    v_filas     NUMBER;
    v_vivas     NUMBER;

    FUNCTION nuevo_uuid RETURN VARCHAR2 IS
    BEGIN
        RETURN LOWER(REGEXP_REPLACE(RAWTOHEX(SYS_GUID()), '(.{8})(.{4})(.{4})(.{4})(.{12})', '\1-\2-\3-\4-\5'));
    END nuevo_uuid;

    PROCEDURE sembrar_rol(p_code VARCHAR2, p_name VARCHAR2, p_order NUMBER) IS
    BEGIN
        MERGE INTO cat_rol d
        USING (SELECT p_code AS role_code FROM dual) s
           ON (d.role_code = s.role_code)
        WHEN NOT MATCHED THEN
            INSERT (role_code, role_name, display_order, is_active)
            VALUES (p_code, p_name, p_order, 'Y');
    END sembrar_rol;
BEGIN
    sembrar_rol('EMPLEADO', 'Empleado', 951);

    INSERT INTO usuario (full_name, corporate_email, username, role_code, password_hash, password_algorithm)
         VALUES ('Oraculo Sesion Idempotente', 'oraculo.tsk051.idempotente@example.invalid',
                 'oraculo.tsk051.idempotente@example.invalid', 'EMPLEADO', 'hash-oraculo-tsk051', 'argon2id')
      RETURNING user_id INTO v_user;

    v_sid  := nuevo_uuid;
    v_rev1 := v_t0 + INTERVAL '1' HOUR;

    INSERT INTO sesion_usuario (session_id, user_id, role_code, issued_at, expires_at, last_activity_at)
         VALUES (v_sid, v_user, 'EMPLEADO', v_t0, v_t0 + INTERVAL '8' HOUR, v_t0);

    -- Primer cierre de sesion explicito (REQ-057): revoked_at informado con motivo 'logout'.
    UPDATE sesion_usuario
       SET revoked_at = v_rev1, revocation_reason = 'logout', last_activity_at = v_rev1
     WHERE session_id = v_sid;

    -- Segundo cierre sobre la misma sesion, con otro instante y otro motivo: debe ser INOCUO.
    UPDATE sesion_usuario
       SET revoked_at        = v_t0 + INTERVAL '5' HOUR,
           revocation_reason = 'admin',
           last_activity_at  = v_t0 + INTERVAL '5' HOUR,
           expires_at        = v_t0 + INTERVAL '48' HOUR
     WHERE session_id = v_sid;
    v_afectadas := SQL%ROWCOUNT;

    IF v_afectadas <> 1 THEN
        RAISE_APPLICATION_ERROR(-20951, 'ORACULO AC-SES-03: la segunda revocacion afecto a ' || v_afectadas || ' filas en lugar de a la misma unica fila');
    END IF;

    SELECT COUNT(*) INTO v_filas FROM sesion_usuario WHERE user_id = v_user;
    IF v_filas <> 1 THEN
        RAISE_APPLICATION_ERROR(-20952, 'ORACULO AC-SES-03: la segunda revocacion ha dejado ' || v_filas || ' sesiones en lugar de la misma fila');
    END IF;

    SELECT revoked_at, revocation_reason, revocation_cause
      INTO v_rev2, v_reason, v_cause
      FROM sesion_usuario WHERE session_id = v_sid;

    IF v_rev2 <> v_rev1 THEN
        RAISE_APPLICATION_ERROR(-20953, 'ORACULO AC-SES-03: revoked_at ha cambiado con la segunda revocacion');
    END IF;
    IF v_reason <> 'logout' THEN
        RAISE_APPLICATION_ERROR(-20954, 'ORACULO AC-SES-03: revocation_reason ha cambiado a ' || v_reason || ' con la segunda revocacion');
    END IF;
    IF v_cause <> 'LOGOUT' THEN
        RAISE_APPLICATION_ERROR(-20955, 'ORACULO REQ-086: la columna virtual revocation_cause vale ' || v_cause || ' en lugar de LOGOUT');
    END IF;

    -- REQ-057 RN-01: una sesion revocada nunca vuelve a ser valida.
    UPDATE sesion_usuario
       SET revoked_at = NULL, revocation_reason = NULL
     WHERE session_id = v_sid;

    SELECT COUNT(*) INTO v_vivas
      FROM sesion_usuario WHERE session_id = v_sid AND revoked_at IS NULL;
    IF v_vivas <> 0 THEN
        RAISE_APPLICATION_ERROR(-20956, 'ORACULO REQ-057 RN-01: una sesion revocada ha vuelto a quedar vigente');
    END IF;

    ROLLBACK;
EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;
        RAISE;
END;

DECLARE
    v_admin       NUMBER;
    v_user        NUMBER;
    v_s1          VARCHAR2(36);
    v_s2          VARCHAR2(36);
    v_t0          TIMESTAMP := SYS_EXTRACT_UTC(SYSTIMESTAMP);
    v_t1          TIMESTAMP;
    v_status      VARCHAR2(10);
    v_sqlcode     NUMBER;
    v_vivas       NUMBER;
    v_revocadas   NUMBER;
    v_invariante  NUMBER;
    v_causa       NUMBER;

    FUNCTION nuevo_uuid RETURN VARCHAR2 IS
    BEGIN
        RETURN LOWER(REGEXP_REPLACE(RAWTOHEX(SYS_GUID()), '(.{8})(.{4})(.{4})(.{4})(.{12})', '\1-\2-\3-\4-\5'));
    END nuevo_uuid;

    PROCEDURE sembrar_rol(p_code VARCHAR2, p_name VARCHAR2, p_order NUMBER) IS
    BEGIN
        MERGE INTO cat_rol d
        USING (SELECT p_code AS role_code FROM dual) s
           ON (d.role_code = s.role_code)
        WHEN NOT MATCHED THEN
            INSERT (role_code, role_name, display_order, is_active)
            VALUES (p_code, p_name, p_order, 'Y');
    END sembrar_rol;
BEGIN
    v_t1 := v_t0 + INTERVAL '2' HOUR;

    sembrar_rol('EMPLEADO', 'Empleado', 951);
    sembrar_rol('ADMINISTRADOR', 'Administrador', 953);

    MERGE INTO cat_motivo_desactivacion d
    USING (SELECT 'BAJA_EMPRESA' AS reason_code FROM dual) s
       ON (d.reason_code = s.reason_code)
    WHEN NOT MATCHED THEN
        INSERT (reason_code, reason_name, is_active)
        VALUES ('BAJA_EMPRESA', 'Baja en la empresa', 'Y');

    INSERT INTO usuario (full_name, corporate_email, username, role_code, password_hash, password_algorithm)
         VALUES ('Oraculo Desactivacion Admin', 'oraculo.tsk051.desact.admin@example.invalid',
                 'oraculo.tsk051.desact.admin@example.invalid', 'ADMINISTRADOR', 'hash-oraculo-tsk051', 'argon2id')
      RETURNING user_id INTO v_admin;

    INSERT INTO usuario (full_name, corporate_email, username, role_code, password_hash, password_algorithm, created_at, created_by)
         VALUES ('Oraculo Desactivacion', 'oraculo.tsk051.desact@example.invalid',
                 'oraculo.tsk051.desact@example.invalid', 'EMPLEADO', 'hash-oraculo-tsk051', 'argon2id', v_t0, v_admin)
      RETURNING user_id INTO v_user;

    v_s1 := nuevo_uuid;
    v_s2 := nuevo_uuid;

    INSERT INTO sesion_usuario (session_id, user_id, role_code, issued_at, expires_at, last_activity_at)
         VALUES (v_s1, v_user, 'EMPLEADO', v_t0, v_t0 + INTERVAL '8' HOUR, v_t0);
    INSERT INTO sesion_usuario (session_id, user_id, role_code, issued_at, expires_at, last_activity_at)
         VALUES (v_s2, v_user, 'EMPLEADO', v_t0 + INTERVAL '1' HOUR, v_t0 + INTERVAL '9' HOUR, v_t0 + INTERVAL '1' HOUR);

    SELECT COUNT(*) INTO v_vivas FROM sesion_usuario WHERE user_id = v_user AND revoked_at IS NULL;
    IF v_vivas <> 2 THEN
        RAISE_APPLICATION_ERROR(-20960, 'ORACULO AC-ACC-01: el escenario deberia partir de 2 sesiones abiertas y hay ' || v_vivas);
    END IF;

    -- AC-ACC-03: si falla la revocacion, la desactivacion se revierte entera.
    SAVEPOINT antes_de_desactivar;

    UPDATE usuario
       SET status = 'INACTIVO', deactivated_at = v_t1, deactivated_by = v_admin,
           deactivation_reason_code = 'BAJA_EMPRESA'
     WHERE user_id = v_user;

    BEGIN
        UPDATE sesion_usuario SET revoked_at = v_t1
         WHERE user_id = v_user AND revoked_at IS NULL;
        v_sqlcode := 0;
    EXCEPTION
        WHEN OTHERS THEN v_sqlcode := SQLCODE;
    END;

    IF v_sqlcode = 0 THEN
        RAISE_APPLICATION_ERROR(-20961, 'ORACULO DoD: revoked_at sin revocation_reason deberia haber sido rechazado por la CHECK');
    END IF;

    ROLLBACK TO SAVEPOINT antes_de_desactivar;

    SELECT status INTO v_status FROM usuario WHERE user_id = v_user;
    IF v_status <> 'ACTIVO' THEN
        RAISE_APPLICATION_ERROR(-20962, 'ORACULO AC-ACC-03: la cuenta quedo en ' || v_status || ' pese a fallar la revocacion de sesiones');
    END IF;

    SELECT COUNT(*) INTO v_vivas FROM sesion_usuario WHERE user_id = v_user AND revoked_at IS NULL;
    IF v_vivas <> 2 THEN
        RAISE_APPLICATION_ERROR(-20963, 'ORACULO AC-ACC-03: tras revertir la desactivacion quedan ' || v_vivas || ' sesiones vivas en lugar de 2');
    END IF;

    -- Desactivacion correcta: cuenta y sesiones en la MISMA transaccion (REQ-086 RN-02).
    UPDATE usuario
       SET status = 'INACTIVO', deactivated_at = v_t1, deactivated_by = v_admin,
           deactivation_reason_code = 'BAJA_EMPRESA'
     WHERE user_id = v_user;

    UPDATE sesion_usuario
       SET revoked_at = v_t1, revocation_reason = 'account_deactivated'
     WHERE user_id = v_user AND revoked_at IS NULL;
    v_revocadas := SQL%ROWCOUNT;

    IF v_revocadas <> 2 THEN
        RAISE_APPLICATION_ERROR(-20964, 'ORACULO AC-ACC-01: la desactivacion revoco ' || v_revocadas || ' sesiones en lugar de las 2 vigentes');
    END IF;

    -- La consulta del invariante (la misma del guardia ddl-0.0.1-08-05) devuelve 0 filas.
    SELECT COUNT(*) INTO v_invariante
      FROM sesion_usuario s
      JOIN usuario u ON u.user_id = s.user_id
     WHERE u.status = 'INACTIVO' AND s.revoked_at IS NULL;
    IF v_invariante <> 0 THEN
        RAISE_APPLICATION_ERROR(-20965, 'ORACULO REQ-086 RN-01: hay ' || v_invariante || ' sesiones vivas sobre cuentas INACTIVO');
    END IF;

    SELECT COUNT(*) INTO v_causa
      FROM sesion_usuario WHERE user_id = v_user AND revocation_cause = 'ACCOUNT_DEACTIVATED';
    IF v_causa <> 2 THEN
        RAISE_APPLICATION_ERROR(-20966, 'ORACULO REQ-086 RN-07: solo ' || v_causa || ' sesiones publican revocation_cause = ACCOUNT_DEACTIVATED');
    END IF;

    -- AC-ACC-04: la reactivacion no restituye ninguna sesion revocada.
    UPDATE usuario
       SET status = 'ACTIVO', deactivated_at = NULL, deactivated_by = NULL,
           deactivation_reason_code = NULL
     WHERE user_id = v_user;

    UPDATE sesion_usuario SET revoked_at = NULL, revocation_reason = NULL WHERE user_id = v_user;

    SELECT COUNT(*) INTO v_vivas FROM sesion_usuario WHERE user_id = v_user AND revoked_at IS NULL;
    IF v_vivas <> 0 THEN
        RAISE_APPLICATION_ERROR(-20967, 'ORACULO AC-ACC-04: la reactivacion ha restituido ' || v_vivas || ' sesiones revocadas');
    END IF;

    ROLLBACK;
EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;
        RAISE;
END;

DECLARE
    v_user       NUMBER;
    v_otro       NUMBER;
    v_ejecutora  VARCHAR2(36);
    v_otra       VARCHAR2(36);
    v_ajena      VARCHAR2(36);
    v_nueva      VARCHAR2(36);
    v_t0         TIMESTAMP := SYS_EXTRACT_UTC(SYSTIMESTAMP);
    v_cambio     TIMESTAMP;
    v_vivas      NUMBER;
    v_superviv   VARCHAR2(36);
    v_motivo     VARCHAR2(30);
    v_ajenas     NUMBER;
    v_previas    NUMBER;
    v_repetido   NUMBER;

    FUNCTION nuevo_uuid RETURN VARCHAR2 IS
    BEGIN
        RETURN LOWER(REGEXP_REPLACE(RAWTOHEX(SYS_GUID()), '(.{8})(.{4})(.{4})(.{4})(.{12})', '\1-\2-\3-\4-\5'));
    END nuevo_uuid;

    PROCEDURE sembrar_rol(p_code VARCHAR2, p_name VARCHAR2, p_order NUMBER) IS
    BEGIN
        MERGE INTO cat_rol d
        USING (SELECT p_code AS role_code FROM dual) s
           ON (d.role_code = s.role_code)
        WHEN NOT MATCHED THEN
            INSERT (role_code, role_name, display_order, is_active)
            VALUES (p_code, p_name, p_order, 'Y');
    END sembrar_rol;
BEGIN
    v_cambio := v_t0 + INTERVAL '2' HOUR;

    sembrar_rol('EMPLEADO', 'Empleado', 951);

    INSERT INTO usuario (full_name, corporate_email, username, role_code, password_hash, password_algorithm)
         VALUES ('Oraculo Cambio Password', 'oraculo.tsk051.pwd@example.invalid',
                 'oraculo.tsk051.pwd@example.invalid', 'EMPLEADO', 'hash-oraculo-anterior', 'argon2id')
      RETURNING user_id INTO v_user;

    INSERT INTO usuario (full_name, corporate_email, username, role_code, password_hash, password_algorithm)
         VALUES ('Oraculo Cambio Password Ajeno', 'oraculo.tsk051.pwd.ajeno@example.invalid',
                 'oraculo.tsk051.pwd.ajeno@example.invalid', 'EMPLEADO', 'hash-oraculo-ajeno', 'argon2id')
      RETURNING user_id INTO v_otro;

    v_ejecutora := nuevo_uuid;
    v_otra      := nuevo_uuid;
    v_ajena     := nuevo_uuid;

    -- Dos navegadores del mismo usuario y una sesion de un usuario ajeno.
    INSERT INTO sesion_usuario (session_id, user_id, role_code, issued_at, expires_at, last_activity_at)
         VALUES (v_ejecutora, v_user, 'EMPLEADO', v_t0, v_t0 + INTERVAL '8' HOUR, v_t0);
    INSERT INTO sesion_usuario (session_id, user_id, role_code, issued_at, expires_at, last_activity_at)
         VALUES (v_otra, v_user, 'EMPLEADO', v_t0 + INTERVAL '1' HOUR, v_t0 + INTERVAL '9' HOUR, v_t0 + INTERVAL '1' HOUR);
    INSERT INTO sesion_usuario (session_id, user_id, role_code, issued_at, expires_at, last_activity_at)
         VALUES (v_ajena, v_otro, 'EMPLEADO', v_t0, v_t0 + INTERVAL '8' HOUR, v_t0);

    -- Cambio de contrasenia ejecutado por el titular desde v_ejecutora (REQ-070).
    UPDATE usuario
       SET password_hash = 'hash-oraculo-nuevo', password_updated_at = v_cambio,
           must_change_password = 'N'
     WHERE user_id = v_user;

    UPDATE sesion_usuario
       SET revoked_at = v_cambio, revocation_reason = 'password_change'
     WHERE user_id = v_user
       AND revoked_at IS NULL
       AND session_id <> v_ejecutora;

    SELECT COUNT(*) INTO v_vivas FROM sesion_usuario WHERE user_id = v_user AND revoked_at IS NULL;
    IF v_vivas <> 1 THEN
        RAISE_APPLICATION_ERROR(-20970, 'ORACULO AC-PWD-05: tras el cambio de contrasenia quedan ' || v_vivas || ' sesiones vivas en lugar de 1');
    END IF;

    SELECT session_id INTO v_superviv FROM sesion_usuario WHERE user_id = v_user AND revoked_at IS NULL;
    IF v_superviv <> v_ejecutora THEN
        RAISE_APPLICATION_ERROR(-20971, 'ORACULO AC-PWD-05: la sesion superviviente no es la ejecutora del cambio');
    END IF;

    SELECT revocation_reason INTO v_motivo FROM sesion_usuario WHERE session_id = v_otra;
    IF v_motivo <> 'password_change' THEN
        RAISE_APPLICATION_ERROR(-20972, 'ORACULO REQ-070: la sesion del otro navegador se revoco con motivo ' || v_motivo);
    END IF;

    SELECT COUNT(*) INTO v_previas
      FROM sesion_usuario s
      JOIN usuario u ON u.user_id = s.user_id
     WHERE s.user_id = v_user
       AND s.revoked_at IS NULL
       AND u.password_updated_at IS NOT NULL
       AND s.issued_at < u.password_updated_at
       AND s.session_id <> v_ejecutora;
    IF v_previas <> 0 THEN
        RAISE_APPLICATION_ERROR(-20973, 'ORACULO REQ-070 RN-01: hay ' || v_previas || ' sesiones anteriores a password_updated_at todavia vigentes');
    END IF;

    SELECT COUNT(*) INTO v_ajenas FROM sesion_usuario WHERE user_id = v_otro AND revoked_at IS NULL;
    IF v_ajenas <> 1 THEN
        RAISE_APPLICATION_ERROR(-20974, 'ORACULO REQ-070 RN-04: la revocacion ha alcanzado las sesiones de otro usuario');
    END IF;

    -- AC-SES-03: el nuevo inicio de sesion emite un session_id distinto del de las sesiones previas.
    v_nueva := nuevo_uuid;
    INSERT INTO sesion_usuario (session_id, user_id, role_code, issued_at, expires_at, last_activity_at)
         VALUES (v_nueva, v_user, 'EMPLEADO', v_cambio, v_cambio + INTERVAL '8' HOUR, v_cambio);

    IF v_nueva = v_ejecutora OR v_nueva = v_otra THEN
        RAISE_APPLICATION_ERROR(-20975, 'ORACULO AC-SES-03: el nuevo inicio de sesion ha reutilizado un session_id anterior');
    END IF;

    SELECT COUNT(DISTINCT session_id) INTO v_repetido FROM sesion_usuario WHERE user_id = v_user;
    IF v_repetido <> 3 THEN
        RAISE_APPLICATION_ERROR(-20976, 'ORACULO AC-SES-03: se esperaban 3 session_id distintos para el usuario y hay ' || v_repetido);
    END IF;

    ROLLBACK;
EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;
        RAISE;
END;
